CREATE OR REPLACE PROCEDURE recalc_market_impact_cost()
LANGUAGE plpgsql
AS $$
DECLARE
    v_fund_rate REAL;
    v_order_record RECORD;
    v_quantity REAL;
    v_limit_price REAL;
    v_large_order_ratio REAL;
    v_mic NUMERIC;
BEGIN
    -- Get the current market factor (fundRate from marketstats)
    SELECT "fundRate" INTO v_fund_rate
    FROM marketstats
    ORDER BY "FundSpot" DESC
    LIMIT 1;

    -- Calculate MIC for each new order and log it
    FOR v_order_record IN
        SELECT o."ORD_STAMP",
               o.order_attributes->>'quantity' AS qty,
               o.order_attributes->>'limit_price' AS lp,
               ai.indicator_bundle->'order_flow'->>'large_order_ratio' AS lor
        FROM orders o
        JOIN analyticsindicators ai ON o."exchSpot" = ai.md_ref
        WHERE o.order_attributes->>'status' = 'New'
    LOOP
        v_quantity := COALESCE(v_order_record.qty::REAL, 0);
        v_limit_price := COALESCE(v_order_record.lp::REAL, 0);
        v_large_order_ratio := COALESCE(v_order_record.lor::REAL, 0);

        -- MIC = order quantity × limit price × large order ratio × 0.01
        v_mic := v_quantity * v_limit_price * v_large_order_ratio * 0.01;

        -- Log the MIC value
        INSERT INTO market_impact_cost_log (ordersmark, mic)
        VALUES (v_order_record."ORD_STAMP", v_mic);
    END LOOP;
END;
$$;

